-- Saldo físico persistente no caixa entre sessões
ALTER TABLE public.restaurants ADD COLUMN IF NOT EXISTS saldo_caixa DECIMAL(12,2) NOT NULL DEFAULT 0;

-- Registro de como o saldo foi destinado no fechamento
ALTER TABLE public.caixas ADD COLUMN IF NOT EXISTS destinacao_fechamento JSONB;

content.content:
1	import React, { useState, useEffect } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { getRelatorio, getMinhaEmpresa, getCaixa, getCaixaHistorico, aprovarConferencia, getConfig } from '../../services/restauranteService';
4	import Icon from '../../components/AppIcon';
5	import CaixaAtualPanel from './CaixaAtualPanel';
6	import HistoricoCaixasPanel from './HistoricoCaixasPanel';
7	import { useSolicitacoesMotoboyCount } from '../../hooks/useSolicitacoesMotoboyCount';
8	import { useMinhaLojaSlug } from '../../hooks/useMinhaLojaSlug';
9	
10	const fmt      = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
11	const fmtDate  = (d) => d ? new Date(d).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—';
12	const today    = () => new Date().toISOString().slice(0, 10);
13	const thisMonth = () => new Date().toISOString().slice(0, 7);
14	const thisYear  = () => new Date().getFullYear().toString();
15	const startOf   = (d) => new Date(d + 'T00:00:00-03:00').toISOString();
16	const endOf     = (d) => new Date(d + 'T23:59:59-03:00').toISOString();
17	const lastDay   = (ym) => { const [y, m] = ym.split('-').map(Number); return new Date(y, m, 0).getDate(); };
18	const ANOS      = Array.from({ length: 4 }, (_, i) => String(new Date().getFullYear() - i));
19	const MODOS     = [{ value: 'dia', label: 'Dia' }, { value: 'mes', label: 'Mês' }, { value: 'ano', label: 'Ano' }, { value: 'periodo', label: 'Período' }];
20	const PAYMENT_LABELS = { pix: 'PIX', credit_card: 'Cartão Crédito', debit_card: 'Cartão Débito', cash: 'Dinheiro' };
21	const PAYMENT_ICONS  = { pix: 'QrCode', credit_card: 'CreditCard', debit_card: 'CreditCard', cash: 'Banknote' };
22	const PAYMENT_COLORS = { pix: 'border-blue-200 bg-blue-50 text-blue-800', credit_card: 'border-purple-200 bg-purple-50 text-purple-800', debit_card: 'border-indigo-200 bg-indigo-50 text-indigo-800', cash: 'border-green-200 bg-green-50 text-green-800' };
23	const STATUS_LABELS  = { pending: 'Recebido', confirmed: 'Confirmado', preparing: 'Em Preparo', ready: 'Pronto', motoboy_collecting: 'Motoboy', out_for_delivery: 'Em Entrega', delivered: 'Entregue', canceled: 'Cancelado' };
24	const STATUS_COLORS  = { pending: 'bg-yellow-100 text-yellow-800', confirmed: 'bg-blue-100 text-blue-800', preparing: 'bg-orange-100 text-orange-800', ready: 'bg-purple-100 text-purple-800', motoboy_collecting: 'bg-sky-100 text-sky-800', out_for_delivery: 'bg-indigo-100 text-indigo-800', delivered: 'bg-green-100 text-green-800', canceled: 'bg-red-100 text-red-800' };
25	
26	const PRINT_STYLE = `*{margin:0;padding:0;box-sizing:border-box}body{font-family:Arial,sans-serif;font-size:12px;padding:16px;max-width:800px;margin:0 auto}h1{font-size:18px;font-weight:900;margin-bottom:2px}h2{font-size:13px;font-weight:700;margin:14px 0 6px;border-bottom:1px solid #ddd;padding-bottom:4px}.sub{font-size:11px;color:#555;margin-bottom:12px}table{width:100%;border-collapse:collapse;margin-bottom:12px;font-size:11px}th{background:#f0f0f0;padding:6px 8px;text-align:left;font-weight:700;border:1px solid #ddd}td{padding:5px 8px;border:1px solid #ddd}.right{text-align:right}.bold{font-weight:700}.green{color:#166534}.red{color:#991b1b}.kpi{display:inline-block;border:1px solid #ddd;border-radius:6px;padding:8px 14px;margin:4px;text-align:center;min-width:120px}.kpi .val{font-size:18px;font-weight:900;display:block}.kpi .lbl{font-size:10px;color:#555}@media print{button{display:none!important}}`;
27	const buildPrint = (dados, nome, label) => {
28	  const r = dados.resumo;
29	  const pgto = Object.entries(r.por_pagamento ?? {}).map(([k, v]) => `<tr><td>${PAYMENT_LABELS[k] ?? k}</td><td class="right">${v.count}</td><td class="right bold green">${fmt(v.total)}</td></tr>`).join('');
30	  const saidasRows = (dados.saidas ?? []).map((s) => `<tr><td>${fmtDate(s.criado_em)}</td><td>${s.descricao}</td><td class="right bold red">- ${fmt(s.valor)}</td></tr>`).join('');
31	  return `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Relatório Financeiro</title><style>${PRINT_STYLE}</style></head><body><h1>${nome ?? 'RESTAURANTE'}</h1><div class="sub">Relatório Financeiro — ${label}</div><div><div class="kpi"><span class="val green">${fmt(r.total_vendas)}</span><span class="lbl">Faturamento</span></div><div class="kpi"><span class="val red">- ${fmt(r.total_saidas)}</span><span class="lbl">Saídas</span></div><div class="kpi"><span class="val">${fmt(r.saldo_liquido)}</span><span class="lbl">Saldo Líquido</span></div><div class="kpi"><span class="val">${r.total_pedidos}</span><span class="lbl">Pedidos</span></div></div><h2>Por Forma de Pagamento</h2><table><tr><th>Método</th><th class="right">Qtd</th><th class="right">Total</th></tr>${pgto}</table>${(dados.saidas ?? []).length > 0 ? `<h2>Saídas</h2><table><tr><th>Data</th><th>Descrição</th><th class="right">Valor</th></tr>${saidasRows}</table>` : ''}<footer>Emitido em: ${new Date().toLocaleString('pt-BR')}</footer><script>window.print();setTimeout(()=>{try{window.frameElement.parentNode.removeChild(window.frameElement)}catch(e){}},2000)</script></body></html>`;
32	};
33	const printIframe = (html) => {
34	  const f = document.createElement('iframe');
35	  f.style.cssText = 'position:fixed;bottom:-1px;left:-1px;width:1px;height:1px;border:0;opacity:0;pointer-events:none';
36	  document.body.appendChild(f);
37	  try { f.contentDocument.open(); f.contentDocument.write(html); f.contentDocument.close(); }
38	  catch { f.remove(); const w = window.open('', '_blank'); if (w) { w.document.write(html); w.document.close(); } }
39	};
40	
41	const LINKS = [
42	  { label: 'Dashboard', path: '/restaurante' },
43	  { label: 'Cozinha', path: '/restaurante/cozinha' },
44	  { label: 'Produtos', path: '/restaurante/produtos' },
45	  { label: 'Pedidos', path: '/restaurante/pedidos' },
46	  { label: 'Entregas', path: '/restaurante/entregas' },
47	  { label: 'Motoboys', path: '/restaurante/motoboys' },
48	  { label: 'Clientes', path: '/restaurante/clientes' },
49	  { label: 'Financeiro', path: '/restaurante/financeiro' },
50	  { label: 'Designer', path: '/restaurante/aparencia' },
51	  { label: 'Config', path: '/restaurante/config' },
52	];
53	
54	const buildRange = (modo, dia, mes, ano, ini, fim) => {
55	  if (modo === 'dia')     return { de: startOf(dia), ate: endOf(dia), label: new Date(dia + 'T12:00:00').toLocaleDateString('pt-BR') };
56	  if (modo === 'mes') { const [y, m] = mes.split('-'); return { de: startOf(`${y}-${m}-01`), ate: endOf(`${y}-${m}-${String(lastDay(mes)).padStart(2, '0')}`), label: new Date(mes + '-01T12:00:00').toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' }) }; }
57	  if (modo === 'ano')     return { de: startOf(`${ano}-01-01`), ate: endOf(`${ano}-12-31`), label: `Ano ${ano}` };
58	  if (modo === 'periodo') return { de: startOf(ini), ate: endOf(fim), label: `${new Date(ini + 'T12:00:00').toLocaleDateString('pt-BR')} a ${new Date(fim + 'T12:00:00').toLocaleDateString('pt-BR')}` };
59	  return null;
60	};
61	
62	const RestauranteFinanceiro = () => {
63	  const navigate = useNavigate();
64	  const pendentesMotoboy = useSolicitacoesMotoboyCount();
65	  const slugLoja = useMinhaLojaSlug();
66	  const [restauranteNome, setRestauranteNome] = useState('');
67	  const [modo, setModo] = useState('dia');
68	  const [dia, setDia]   = useState(today());
69	  const [mes, setMes]   = useState(thisMonth());
70	  const [ano, setAno]   = useState(thisYear());
71	  const [ini, setIni]   = useState(today());
72	  const [fim, setFim]   = useState(today());
73	  const [dados, setDados]     = useState(null);
74	  const [label, setLabel]     = useState('');
75	  const [loading, setLoading] = useState(false);
76	  const [erro, setErro]       = useState(null);
77	  const [abaAtiva, setAbaAtiva] = useState('resumo');
78	  const [caixa, setCaixa]     = useState(null);
79	  const [historico, setHistorico] = useState([]);
80	  const [aprovando, setAprovando] = useState(null);
81	  const [taxaPagbank, setTaxaPagbank] = useState(0);
82	
83	  const conferenciasPendentes = historico.filter(
84	    (cx) => cx.status === 'fechado' && cx.destinacao_fechamento?.conferencia_aprovada === false,
85	  );
86	
87	  const carregarDados = async () => {
88	    const [c, hist] = await Promise.all([getCaixa(), getCaixaHistorico()]);
89	    setCaixa(c);
90	    setHistorico(hist.historico ?? []);
91	  };
92	
93	  useEffect(() => {
94	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
95	    getConfig().then((cfg) => setTaxaPagbank(cfg.taxa_pagbank_percent ?? 0)).catch(() => {});
96	    carregarDados().catch(() => {});
97	    buscar();
98	  }, []); // eslint-disable-line
99	
100	  const buscar = async () => {
101	    const range = buildRange(modo, dia, mes, ano, ini, fim);
102	    if (!range) return;
103	    setLoading(true); setErro(null);
104	    try { const d = await getRelatorio(range.de, range.ate); setDados(d); setLabel(range.label); }
105	    catch (e) { setErro(e.message); }
106	    finally { setLoading(false); }
107	  };
108	
109	  const handleAprovarConferencia = async (caixaId) => {
110	    setAprovando(caixaId);
111	    try { await aprovarConferencia(caixaId); await carregarDados(); }
112	    catch (e) { alert(e.message ?? 'Erro ao aprovar'); }
113	    finally { setAprovando(null); }
114	  };
115	
116	  const r = dados?.resumo;
117	  const cashTotal    = r?.por_pagamento?.cash?.total ?? 0;
118	  const digitalTotal = Object.entries(r?.por_pagamento ?? {}).filter(([k]) => k !== 'cash').reduce((s, [, v]) => s + v.total, 0);
119	
120	  return (
121	    <div className="min-h-screen bg-[#FAFAFA]">
122	      <header className="bg-white border-b border-[#E4E4E7] px-6 py-4 flex items-center justify-between">
123	        <div>
124	          <h1 className="text-xl font-bold text-[#18181B]">Financeiro</h1>
125	          <p className="text-sm text-[#71717A]">Gestão financeira gerencial</p>
126	        </div>
127	        <nav className="hidden md:flex gap-1.5 flex-wrap items-center">
128	          {LINKS.map((l) => (
129	            <button key={l.path} onClick={() => navigate(l.path)}
130	              className={`relative px-3 py-2 text-sm font-semibold rounded-lg transition-colors ${l.path === '/restaurante/financeiro' ? 'text-white bg-[#FF441F] shadow-sm shadow-[#FF441F]/30' : 'text-[#27272A] hover:bg-[#F4F4F5]'}`}>
131	              {l.label}
132	              {l.path === '/restaurante/motoboys' && pendentesMotoboy > 0 && (
133	                <span className="absolute -top-1 -right-1 min-w-[18px] h-[18px] px-1 flex items-center justify-center bg-red-500 text-white text-[10px] font-bold rounded-full border-2 border-white">
134	                  {pendentesMotoboy}
135	                </span>
136	              )}
137	            </button>
138	          ))}
139	          {slugLoja && (
140	            <button onClick={() => window.open(`/r/${slugLoja}`, '_blank')}
141	              className="px-3 py-2 text-sm font-semibold rounded-lg text-green-700 bg-green-50 hover:bg-green-100 border border-green-200 flex items-center gap-1.5">
142	              <Icon name="ExternalLink" size={14} /> Loja
143	            </button>
144	          )}
145	        </nav>
146	        <button onClick={() => navigate('/restaurante')} className="md:hidden flex items-center gap-1.5 text-sm text-[#71717A]">
147	          <Icon name="ChevronLeft" size={16} /> Voltar
148	        </button>
149	      </header>
150	
151	      <main className="p-6 w-[95%] mx-auto max-w-5xl space-y-5">
152	
153	        {/* Caixa Atual */}
154	        {caixa?.aberto
155	          ? <CaixaAtualPanel caixa={caixa} taxaPagbank={taxaPagbank} onRefresh={carregarDados} />
156	          : caixa && (
157	            <div className="bg-white rounded-2xl border border-[#E4E4E7] p-5 flex items-center gap-4">
158	              <div className="w-10 h-10 rounded-xl bg-[#F4F4F5] flex items-center justify-center flex-shrink-0">
159	                <Icon name="Lock" size={18} className="text-[#A1A1AA]" />
160	              </div>
161	              <div>
162	                <p className="text-sm font-bold text-[#18181B]">Caixa Fechado</p>
163	                <p className="text-xs text-[#71717A]">Abra o caixa no Dashboard para iniciar uma sessão.</p>
164	              </div>
165	            </div>
166	          )
167	        }
168	
169	        {/* Conferências Pendentes */}
170	        {conferenciasPendentes.length > 0 && (
171	          <div className="bg-white rounded-2xl border border-amber-200 p-5">
172	            <p className="text-sm font-bold text-[#18181B] mb-1">Conferências Pendentes</p>
173	            <p className="text-[10px] text-[#71717A] mb-3">Fechamentos aguardando aprovação do gerente</p>
174	            <div className="space-y-3">
175	              {conferenciasPendentes.map((cx) => {
176	                const d   = cx.destinacao_fechamento ?? {};
177	                const dif = d.diferenca ?? 0;
178	                const difCor = dif === 0 ? 'text-green-700' : dif > 0 ? 'text-blue-600' : 'text-red-600';
179	                return (
180	                  <div key={cx.id} className="border border-[#E4E4E7] rounded-xl p-3">
181	                    <div className="flex items-start justify-between gap-2 mb-2">
182	                      <div>
183	                        <p className="text-sm font-semibold text-[#18181B]">{cx.nome_operador}</p>
184	                        <p className="text-[10px] text-[#71717A]">{fmtDate(cx.fechado_em)}</p>
185	                      </div>
186	                      <button onClick={() => handleAprovarConferencia(cx.id)} disabled={aprovando === cx.id}
187	                        className="px-3 py-1.5 text-xs font-bold bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:opacity-50 flex-shrink-0">
188	                        {aprovando === cx.id ? '...' : 'Aprovar'}
189	                      </button>
190	                    </div>
191	                    <div className="grid grid-cols-3 gap-2 text-center text-[11px]">
192	                      <div className="bg-[#FAFAFA] rounded-lg p-2"><p className="text-[#71717A]">Esperado</p><p className="font-bold text-[#18181B]">{fmt(d.especie_calculada)}</p></div>
193	                      <div className="bg-[#FAFAFA] rounded-lg p-2"><p className="text-[#71717A]">Contou</p><p className="font-bold text-[#18181B]">{fmt(d.dinheiro_contado)}</p></div>
194	                      <div className="bg-[#FAFAFA] rounded-lg p-2"><p className="text-[#71717A]">Diferença</p><p className={`font-bold ${difCor}`}>{dif > 0 ? '+' : ''}{fmt(dif)}</p></div>
195	                    </div>
196	                  </div>
197	                );
198	              })}
199	            </div>
200	          </div>
201	        )}
202	
203	        {/* Análise por Período */}
204	        <div className="bg-white rounded-2xl border border-[#E4E4E7] p-4">
205	          <p className="text-xs font-black text-[#A1A1AA] uppercase tracking-widest mb-3">Análise por Período</p>
206	          <div className="flex flex-wrap gap-2 items-end">
207	            <div className="flex gap-1 bg-[#F4F4F5] p-1 rounded-xl">
208	              {MODOS.map((m) => (
209	                <button key={m.value} onClick={() => setModo(m.value)}
210	                  className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-colors ${modo === m.value ? 'bg-white text-[#18181B] shadow-sm' : 'text-[#71717A] hover:text-[#27272A]'}`}>
211	                  {m.label}
212	                </button>
213	              ))}
214	            </div>
215	            {modo === 'dia'     && <input type="date" value={dia} onChange={(e) => setDia(e.target.value)} className="border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />}
216	            {modo === 'mes'     && <input type="month" value={mes} onChange={(e) => setMes(e.target.value)} className="border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />}
217	            {modo === 'ano'     && <select value={ano} onChange={(e) => setAno(e.target.value)} className="border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]">{ANOS.map((a) => <option key={a}>{a}</option>)}</select>}
218	            {modo === 'periodo' && (
219	              <>
220	                <input type="date" value={ini} onChange={(e) => setIni(e.target.value)} className="border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
221	                <span className="text-sm text-[#71717A] self-center">até</span>
222	                <input type="date" value={fim} min={ini} onChange={(e) => setFim(e.target.value)} className="border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
223	              </>
224	            )}
225	            <button onClick={buscar} disabled={loading}
226	              className="flex items-center gap-2 px-4 py-2 bg-[#FF441F] text-white text-sm font-bold rounded-xl hover:bg-[#E63A19] disabled:opacity-50">
227	              {loading ? <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" /> : <Icon name="Search" size={14} />}
228	              Buscar
229	            </button>
230	            {dados && (
231	              <button onClick={() => printIframe(buildPrint(dados, restauranteNome, label))}
232	                className="flex items-center gap-2 px-4 py-2 border border-[#E4E4E7] rounded-xl text-sm font-bold text-[#27272A] hover:bg-[#F4F4F5]">
233	                <Icon name="Printer" size={14} /> Imprimir
234	              </button>
235	            )}
236	          </div>
237	          {erro && <p className="text-sm text-red-600 bg-red-50 px-3 py-2 rounded-xl mt-3">{erro}</p>}
238	        </div>
239	
240	        {dados && r && (
241	          <>
242	            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
243	              <div className="bg-white border border-green-200 rounded-2xl p-4 text-center">
244	                <p className="text-[10px] font-black text-green-600 uppercase tracking-widest mb-1">Faturamento</p>
245	                <p className="text-2xl font-black text-green-700">{fmt(r.total_vendas)}</p>
246	                <p className="text-xs text-[#71717A] mt-1">{r.entregues} pedidos entregues</p>
247	              </div>
248	              <div className="bg-white border border-red-200 rounded-2xl p-4 text-center">
249	                <p className="text-[10px] font-black text-red-600 uppercase tracking-widest mb-1">Saídas</p>
250	                <p className="text-2xl font-black text-red-600">- {fmt(r.total_saidas)}</p>
251	                <p className="text-xs text-[#71717A] mt-1">{(dados.saidas ?? []).length} registros</p>
252	              </div>
253	              <div className={`bg-white border rounded-2xl p-4 text-center ${r.saldo_liquido >= 0 ? 'border-[#FF441F]/30' : 'border-red-200'}`}>
254	                <p className="text-[10px] font-black text-[#71717A] uppercase tracking-widest mb-1">Saldo Líquido</p>
255	                <p className={`text-2xl font-black ${r.saldo_liquido >= 0 ? 'text-[#FF441F]' : 'text-red-600'}`}>{fmt(r.saldo_liquido)}</p>
256	                <p className="text-xs text-[#71717A] mt-1">Faturamento − Saídas</p>
257	              </div>
258	              <div className="bg-white border border-[#E4E4E7] rounded-2xl p-4 text-center">
259	                <p className="text-[10px] font-black text-[#71717A] uppercase tracking-widest mb-1">Ticket Médio</p>
260	                <p className="text-2xl font-black text-[#18181B]">{fmt(r.ticket_medio)}</p>
261	                <p className="text-xs text-[#71717A] mt-1">{r.total_pedidos} pedidos total</p>
262	              </div>
263	            </div>
264	
265	            <div className="flex gap-1 bg-[#F4F4F5] p-1 rounded-xl w-fit">
266	              {[{ id: 'resumo', label: 'Entradas' }, { id: 'canais', label: 'Canais' }, { id: 'saidas', label: `Saídas (${(dados.saidas ?? []).length})` }, { id: 'pedidos', label: `Pedidos (${dados.pedidos?.length ?? 0})` }].map((a) => (
267	                <button key={a.id} onClick={() => setAbaAtiva(a.id)}
268	                  className={`px-4 py-2 text-xs font-bold rounded-lg transition-colors ${abaAtiva === a.id ? 'bg-white text-[#18181B] shadow-sm' : 'text-[#71717A] hover:text-[#27272A]'}`}>
269	                  {a.label}
270	                </button>
271	              ))}
272	            </div>
273	
274	            {abaAtiva === 'resumo' && (
275	              <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-3">
276	                {Object.entries(r.por_pagamento ?? {}).length === 0
277	                  ? <p className="text-sm text-[#71717A] col-span-4 text-center py-6">Nenhuma entrada no período.</p>
278	                  : Object.entries(r.por_pagamento ?? {}).map(([k, v]) => (
279	                    <div key={k} className={`bg-white border rounded-2xl p-4 ${PAYMENT_COLORS[k] ?? 'border-gray-200 bg-gray-50 text-gray-800'}`}>
280	                      <div className="flex items-center gap-2 mb-2"><Icon name={PAYMENT_ICONS[k] ?? 'DollarSign'} size={16} /><p className="text-xs font-bold uppercase tracking-wide">{PAYMENT_LABELS[k] ?? k}</p></div>
281	                      <p className="text-2xl font-black">{fmt(v.total)}</p>
282	                      <p className="text-xs mt-1 opacity-70">{v.count} pedido{v.count !== 1 ? 's' : ''}</p>
283	                    </div>
284	                  ))}
285	              </div>
286	            )}
287	
288	            {abaAtiva === 'canais' && (
289	              <div className="grid md:grid-cols-2 gap-4">
290	                <div className="bg-white border border-green-200 rounded-2xl p-5">
291	                  <div className="flex items-center gap-2 mb-3"><Icon name="Banknote" size={18} className="text-green-600" /><h3 className="font-bold text-[#18181B]">Dinheiro Físico (Caixa)</h3></div>
292	                  <p className="text-3xl font-black text-green-700 mb-1">{fmt(cashTotal)}</p>
293	                  <p className="text-xs text-[#71717A]">{r.por_pagamento?.cash?.count ?? 0} pagamentos em dinheiro</p>
294	                  <div className="mt-4 pt-3 border-t border-green-100">
295	                    <p className="text-xs font-semibold text-green-700">Estimativa em caixa: {fmt(Math.max(0, cashTotal - r.total_saidas))}</p>
296	                  </div>
297	                </div>
298	                <div className="bg-white border border-blue-200 rounded-2xl p-5">
299	                  <div className="flex items-center gap-2 mb-3"><Icon name="Landmark" size={18} className="text-blue-600" /><h3 className="font-bold text-[#18181B]">Digital / Banco (PagBank)</h3></div>
300	                  <p className="text-3xl font-black text-blue-700 mb-1">{fmt(digitalTotal)}</p>
301	                  {taxaPagbank > 0 && <p className="text-xs text-red-500 font-semibold">Taxa est. ({taxaPagbank}%): - {fmt(digitalTotal * taxaPagbank / 100)}</p>}
302	                  <div className="mt-4 pt-3 border-t border-blue-100 space-y-1">
303	                    {Object.entries(r.por_pagamento ?? {}).filter(([k]) => k !== 'cash').map(([k, v]) => (
304	                      <div key={k} className="flex justify-between text-xs"><span className="text-[#71717A]">{PAYMENT_LABELS[k] ?? k}</span><span className="font-semibold">{fmt(v.total)} ({v.count})</span></div>
305	                    ))}
306	                  </div>
307	                </div>
308	              </div>
309	            )}
310	
311	            {abaAtiva === 'saidas' && (
312	              <div className="bg-white rounded-2xl border border-[#E4E4E7] overflow-hidden">
313	                {(dados.saidas ?? []).length === 0
314	                  ? <p className="text-sm text-[#71717A] text-center py-10">Nenhuma saída registrada no período.</p>
315	                  : (
316	                    <div>
317	                      <div className="px-5 py-3 bg-[#FAFAFA] border-b border-[#F4F4F5] flex justify-between text-xs font-bold text-[#71717A] uppercase tracking-widest"><span>Data / Descrição</span><span>Valor</span></div>
318	                      <div className="divide-y divide-[#F4F4F5] max-h-[400px] overflow-y-auto">
319	                        {(dados.saidas ?? []).sort((a, b) => new Date(b.criado_em) - new Date(a.criado_em)).map((s, i) => (
320	                          <div key={i} className="flex items-center justify-between px-5 py-3">
321	                            <div><p className="text-sm font-semibold text-[#18181B]">{s.descricao}</p><p className="text-xs text-[#71717A]">{fmtDate(s.criado_em)}{s.meio && <span className="ml-1.5 px-1.5 py-0.5 bg-[#F4F4F5] rounded text-[10px] capitalize">{s.meio}</span>}</p></div>
322	                            <p className="font-bold text-red-500 text-sm flex-shrink-0">- {fmt(s.valor)}</p>
323	                          </div>
324	                        ))}
325	                      </div>
326	                      <div className="px-5 py-3 bg-red-50 border-t border-red-100 flex justify-between"><span className="text-sm font-bold text-red-700">Total saídas</span><span className="text-sm font-black text-red-700">- {fmt(r.total_saidas)}</span></div>
327	                    </div>
328	                  )}
329	              </div>
330	            )}
331	
332	            {abaAtiva === 'pedidos' && (
333	              <div className="bg-white rounded-2xl border border-[#E4E4E7] overflow-hidden">
334	                {(dados.pedidos ?? []).length === 0
335	                  ? <p className="text-sm text-[#71717A] text-center py-10">Nenhum pedido no período.</p>
336	                  : (
337	                    <div>
338	                      <div className="px-5 py-3 bg-[#FAFAFA] border-b border-[#F4F4F5] grid grid-cols-4 text-xs font-bold text-[#71717A] uppercase tracking-widest"><span>Pedido</span><span>Cliente</span><span>Pagamento</span><span className="text-right">Total</span></div>
339	                      <div className="divide-y divide-[#F4F4F5] max-h-[500px] overflow-y-auto">
340	                        {dados.pedidos.map((p) => (
341	                          <div key={p.id} className="px-5 py-3 grid grid-cols-4 items-center gap-2 hover:bg-[#FAFAFA]">
342	                            <div><div className="flex items-center gap-1.5"><span className="text-sm font-bold">#{p.id}</span><span className={`text-[9px] px-1.5 py-0.5 rounded-full font-semibold ${STATUS_COLORS[p.status] ?? 'bg-gray-100 text-gray-700'}`}>{STATUS_LABELS[p.status] ?? p.status}</span></div><p className="text-[10px] text-[#71717A]">{fmtDate(p.created_at)}</p></div>
343	                            <p className="text-xs truncate">{p.customers?.name ?? '—'}</p>
344	                            <p className="text-xs text-[#71717A]">{PAYMENT_LABELS[p.payment_method] ?? p.payment_method}</p>
345	                            <p className={`text-sm font-bold text-right ${p.status === 'canceled' ? 'text-red-400 line-through' : 'text-[#18181B]'}`}>{fmt(p.total)}</p>
346	                          </div>
347	                        ))}
348	                      </div>
349	                      <div className="px-5 py-3 bg-[#FAFAFA] border-t border-[#E4E4E7] flex justify-between"><span className="text-sm text-[#71717A]">{dados.pedidos.length} pedidos · {r.cancelados} cancelados</span><span className="text-sm font-black text-green-700">{fmt(r.total_vendas)} faturados</span></div>
350	                    </div>
351	                  )}
352	              </div>
353	            )}
354	          </>
355	        )}
356	
357	        {!dados && !loading && (
358	          <div className="bg-white rounded-2xl border border-[#E4E4E7] p-10 text-center">
359	            <Icon name="BarChart2" size={32} className="text-[#D4D4D8] mx-auto mb-3" />
360	            <p className="text-[#71717A]">Selecione o período e clique em Buscar.</p>
361	          </div>
362	        )}
363	
364	        {/* Histórico de Caixas */}
365	        <HistoricoCaixasPanel historico={historico} />
366	
367	      </main>
368	    </div>
369	  );
370	};
371	
372	export default RestauranteFinanceiro;
