                    ))}
                  </div>
                </div>
              </div>
            )}

            {abaAtiva === 'saidas' && (
              <div className="bg-white rounded-2xl border border-[#E4E4E7] overflow-hidden">
                {(dados.saidas ?? []).length === 0
