                  : (
                    <div>
                      <div className="px-5 py-3 bg-[#FAFAFA] border-b border-[#F4F4F5] flex justify-between text-xs font-bold text-[#71717A] uppercase tracking-widest"><span>Data / Descrição</span><span>Valor</span></div>
